def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    # Find the color of the long L-shaped marker.
    from collections import deque
    components = {}
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            components.setdefault(color, []).append(comp)

    marker = None
    for color, comps in components.items():
        for comp in comps:
            rs = [r for r, c in comp]
            cs = [c for r, c in comp]
            if (len(comp) >= 8 and
                (len(set(rs)) == 1 or len(set(cs)) == 1 or
                 (len(set(rs)) >= 4 and len(set(cs)) >= 4))):
                marker = color
                break
        if marker is not None:
            break

    if marker is not None:
        for color, comps in components.items():
            if color != marker:
                for comp in comps:
                    if len(comp) == 1:
                        r, c = comp[0]
                        out[r][c] = marker
                        return out
    return out
